function GlobalSDKCallBack:OnProcessPurchase(json)
    local jsonData = Dll_JSON.decode(json)

    local productId = jsonData["productId"]
    local packageName = jsonData["packageName"]
    local purchaseToken = jsonData["purchaseToken"]
    local orderId = jsonData["orderId"]

    print("处理购买，给服务器发送验证消息", productId, packageName, purchaseToken, orderId)

    ---@type paylist_config
    local cfg = ClientDataManager:Get():GetDataTable(ConfigNames.paylist_config)
    local cell = cfg.GetDataByGoodsId(productId)
    if cell == nil then
        ---@type dictweek_config
        cfg = ClientDataManager:Get():GetDataTable(ConfigNames.dictweek_config)
        ---@type dictweek_config_cell
        cell = cfg.GetDataByGoodsId(productId)
        if cell ~= nil then
            ActivitySubsystem:Get():SendMsg_PayWeekCard(cell.cardId, packageName, productId, purchaseToken)
        end
    else
        ActivitySubsystem:Get():SendMsg_Purchase(packageName, productId, purchaseToken, orderId)
    end
end

---@param errorReason  PurchaseFailureReason
function GlobalSDKCallBack:OnPurchaseFail(errorReason)
    if errorReason == nil then
        errorReason = TemplateStringID.CreateFail
    end
    if errorReason == PurchaseFailureReason.DuplicateTransaction then
        errorReason = TemplateStringID.Purchase_DuplicateTransaction
    elseif errorReason == PurchaseFailureReason.ExistingPurchasePending then
        errorReason = TemplateStringID.Purchase_ExistingPurchasePending
    elseif errorReason == PurchaseFailureReason.PaymentDeclined then
        errorReason = TemplateStringID.PaymentDeclined
    elseif errorReason == PurchaseFailureReason.ProductUnavailable then
        errorReason = TemplateStringID.Purchase_ProductUnavailable
    elseif errorReason == PurchaseFailureReason.PurchasingUnavailable then
        errorReason = TemplateStringID.Purchase_ProductUnavailable
    elseif errorReason == PurchaseFailureReason.Unknown then
        errorReason = TemplateStringID.CreateFail
    elseif errorReason == PurchaseFailureReason.UserCancelled then
        errorReason = TemplateStringID.Purchase_UserCancelled
    else
        errorReason = TemplateStringID.CreateFail
    end
    CommonHelper:PlayScreenEffectWaiting(false)
    CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(errorReason))
end

function GlobalSDKCallBack:OnPurchaseInitFail(errorReason, isConnectGoogle)
    CommonHelper:PlayScreenEffectWaiting(false)
    if isConnectGoogle == true then
        CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.SetErrorWait))
    else
        local boxFunc = function()
            MessageBoxHelp:Get():OpenBox_OK(UIColor.Yellow, CommonHelper:GetTempStr_Default(TemplateStringID.RecruitOpenGooglePlay))
        end
        MessageBoxHelp.Get():StartCoroutineBox(boxFunc)
    end
end

function GlobalSDKCallBack:OnConfirmPurchase(productId, transactionId, price, currency)
    CommonHelper:PlayScreenEffectWaiting(false)

    if not CommonHelper:IsNullOrEmpty(transactionId) then
        ---@type paylist_config
        local paylist_config = ClientDataManager:Get():GetDataTable(ConfigNames.paylist_config)

        ---@type paylist_config_cell
        local cell = paylist_config.GetDataByGoodsId(productId)

        if cell == nil then
            ---@type dictweek_config
            paylist_config = ClientDataManager:Get():GetDataTable(ConfigNames.dictweek_config)
            ---@type dictweek_config_cell
            cell = paylist_config.GetDataByGoodsId(productId)
            --if cell ~= nil then
            --    if cell.price == "NT$ 66.00" then
            --        cell.price = 66
            --    elseif cell.price == "NT$ 170.00" then
            --        cell.price = 170
            --    end
            --end
        end
        --print("---productId", productId, "---transactionId", transactionId, "---price", price, "---currency", currency)
        if cell ~= nil then
            local evenName = ""
            if cell.price == 33 then
                evenName = GlobalAd_EventKey.Ad_In_App_099
            elseif cell.price == 66 then
                evenName = GlobalAd_EventKey.Ad_In_App_199
            elseif cell.price == 170 then
                evenName = GlobalAd_EventKey.Ad_In_App_499
            elseif cell.price == 330 then
                evenName = GlobalAd_EventKey.Ad_In_App_999
            elseif cell.price == 490 then
                evenName = GlobalAd_EventKey.Ad_In_App_1499
            elseif cell.price == 670 then
                evenName = GlobalAd_EventKey.Ad_In_App_1999
            elseif cell.price == 870 then
